#define K1_RTL8852BS_EFUSE_ISO_ENABLE       (1u << 14)
#define K1_RTL8852BS_EFUSE_ISO_STABLE       (1u << 15)
#define K1_RTL8852BS_EFUSE_ISO_BLOCK        (1u << 8)
#define K1_RTL8852BS_EFUSE_PMCR_WRITE       (1u << 2)
