#define K1_RTL8852BS_SIFS_MACTXEN_T1_VALUE   0x00000047u
#define K1_RTL8852BS_SCH_EXT_CTRL            0xc3fcu
#define K1_RTL8852BS_PORT_RST_TSF_ADV        0x00000002u
