#define K1_RTL8852BS_PHY_CR_SENTINELS        5u
#define K1_RTL8852BS_MPDU_PROC_STATIC_MASK   0x00000003u
#define K1_RTL8852BS_MPDU_PROC_STATIC_VALUE  0x00000003u
