#define K1_RTL8852BS_H2C_LOOPBACK_RESPONSE_POLL_COUNT 100u
#define K1_RTL8852BS_H2C_LOOPBACK_RESPONSE_POLL_MSEC 1u
#define K1_RTL8852BS_H2C_LOOPBACK_RXFIFO       0x1f00u
