#define K1_RTL8852BS_RXDESC_SHORT_SIZE          16u
#define K1_RTL8852BS_RXDESC_LONG_SIZE           32u
#define K1_RTL8852BS_RXDESC_LENGTH_MASK         0x00003fffu
#define K1_RTL8852BS_RXDESC_SHIFT               14u
#define K1_RTL8852BS_RXDESC_SHIFT_MASK          0x3u
#define K1_RTL8852BS_RXDESC_PACKET_TYPE_SHIFT   24u
#define K1_RTL8852BS_RXDESC_PACKET_TYPE_MASK    0x0fu
#define K1_RTL8852BS_RXDESC_PACKET_TYPE_WIFI    0u
#define K1_RTL8852BS_RXDESC_DRIVER_INFO_SHIFT   28u
#define K1_RTL8852BS_RXDESC_DRIVER_INFO_MASK    0x7u
#define K1_RTL8852BS_RXDESC_LONG                (1u << 31)
#define K1_RTL8852BS_RXDESC_CRC_ERROR           (1u << 9)
#define K1_RTL8852BS_RXDESC_ICV_ERROR           (1u << 10)

/* What the receive descriptor says about the frame's protection.
 *
 * The three bits next to the two error bits already decoded above live in the
 * same dword 3: a1_match bit 0, sw_dec bit 1, hw_dec bit 2, with_llc bit 25
 * (rtw89_txrx.h RTW89_RXD_A1_MATCH / SW_DEC / HW_DEC / GET_RXINFO_WITH_LLC,
 * mainline rtw89_core_rx_parse_rxdesc_v0()).  hw_dec says the security engine
 * decrypted the frame and sw_dec says it handed the frame over for software to
 * decrypt instead; mainline's own test for a decrypted frame is hw_dec and not
 * (sw_dec or icv_err), and it sets no flag claiming the header or the trailer
 * was stripped, so a decrypted frame still carries its eight-byte CCMP header
 * and its eight-byte MIC.
 *
 * Dword 5 carries which key and which address record the frame matched -
 * sec_cam_idx [7:0], addr_cam [15:8], macid [23:16], addr_cam_vld bit 28 - and
 * dword 7 carries the cipher the engine used, sec_type [20:17], in the same
 * mac_ax_enc_alg encoding the security CAM entry's own type field takes, so
 * CCMP-128 reads back as 6.  Both dwords exist only in the long descriptor
 * form, the one dword 0 bit 31 announces.
 */

#define K1_RTL8852BS_RXDESC_A1_MATCH            (1u << 0)
#define K1_RTL8852BS_RXDESC_SW_DEC              (1u << 1)
#define K1_RTL8852BS_RXDESC_HW_DEC              (1u << 2)
#define K1_RTL8852BS_RXDESC_WITH_LLC            (1u << 25)
#define K1_RTL8852BS_RXDESC_SEC_CAM_IDX_SHIFT   0u
#define K1_RTL8852BS_RXDESC_SEC_CAM_IDX_MASK    0xffu
#define K1_RTL8852BS_RXDESC_ADDR_CAM_SHIFT      8u
#define K1_RTL8852BS_RXDESC_ADDR_CAM_MASK       0xffu
#define K1_RTL8852BS_RXDESC_MAC_ID_SHIFT        16u
#define K1_RTL8852BS_RXDESC_MAC_ID_MASK         0xffu
#define K1_RTL8852BS_RXDESC_ADDR_CAM_VALID      (1u << 28)
#define K1_RTL8852BS_RXDESC_SEC_TYPE_SHIFT      17u
#define K1_RTL8852BS_RXDESC_SEC_TYPE_MASK       0xfu

/* The report the hardware sends back once it has finished with a frame this
 * host asked it to transmit.  It arrives on the receive path as a packet type
 * of its own -- rpkt_type 6, RTW89_CORE_RX_TYPE_TX_REPORT in mainline's
 * enum rtw89_core_rx_type, the same enumeration whose 0 and 10 this path
 * already depends on for air frames and for C2H -- and its body is the six
 * words the vendor tree lays out in mac_8852b/mac_txccxrpt.h and reads back
 * in fwofld.c's mac_ccxrpt_parsing() and get_ccxrpt_event(): word 0 for the
 * transmit state, the software tag and the MACID, word 3 for the two packet
 * counts.  A transmit state of zero is that same file's own test for a frame
 * the peer acknowledged, and that is the one reading the MAC's transmit
 * counters cannot give.  They say a frame left the MAC; they do not say
 * anybody answered it.
 *
 * Run 43's log is the evidence that these reports already arrive.  The scan
 * window's per-type histogram counted 22, 5 and 27 packets of type 6 in
 * exactly the three windows this port transmitted management frames in, and
 * none in any other window, so the hardware has been reporting on this
 * port's own transmissions all along while the receive drain discarded them.
 * Nothing in the descriptor or in the report path has to be switched on for
 * this; only the discarding has to stop.
 */

#define K1_RTL8852BS_RXDESC_PACKET_TYPE_TXRPT   6u
#define K1_RTL8852BS_TXRPT_WORDS                6u
#define K1_RTL8852BS_TXRPT_SIZE                 (K1_RTL8852BS_TXRPT_WORDS * 4u)
#define K1_RTL8852BS_TXRPT_RPT_SEL_MASK         0x1fu
#define K1_RTL8852BS_TXRPT_POLLUTED             (1u << 5)
#define K1_RTL8852BS_TXRPT_TX_STATE_SHIFT       6u
#define K1_RTL8852BS_TXRPT_TX_STATE_MASK        0x3u
#define K1_RTL8852BS_TXRPT_TX_STATE_OK          0u
#define K1_RTL8852BS_TXRPT_SW_DEFINE_SHIFT      8u
#define K1_RTL8852BS_TXRPT_SW_DEFINE_MASK       0xfu
#define K1_RTL8852BS_TXRPT_MACID_SHIFT          16u
#define K1_RTL8852BS_TXRPT_MACID_MASK           0x7fu
#define K1_RTL8852BS_TXRPT_QSEL_SHIFT           24u
#define K1_RTL8852BS_TXRPT_QSEL_MASK            0x3fu
#define K1_RTL8852BS_TXRPT_QUEUE_TIME_MASK      0xffffu
#define K1_RTL8852BS_TXRPT_FINAL_RATE_MASK      0x1ffu
#define K1_RTL8852BS_TXRPT_TOTAL_PKT_NUM_MASK   0xffu
#define K1_RTL8852BS_TXRPT_DATA_TX_CNT_SHIFT    8u
#define K1_RTL8852BS_TXRPT_DATA_TX_CNT_MASK     0x3fu
#define K1_RTL8852BS_TXRPT_PKT_OK_NUM_SHIFT     16u
#define K1_RTL8852BS_TXRPT_PKT_OK_NUM_MASK      0xffu
#define K1_RTL8852BS_TXRPT_RTS_TX_COUNT_SHIFT   24u
#define K1_RTL8852BS_TXRPT_RTS_TX_COUNT_MASK    0x3fu

/* Asking for one of those reports on a frame this port transmits, and
 * recognising the answer.
 *
 * Run 49 is the reading that makes this necessary.  The dwell instrument
 * decoded its first type-6 packet and every field of it was zero except the
 * report selector: no MACID, no queue selector, no counts.  A report about a
 * management frame of this port's would carry queue selector 0x12, the band-0
 * management queue its descriptor names, so those packets are not reports
 * about this port's frames at all -- and the resident window, which transmits
 * on the best-effort queue, has collected none of any kind across four runs.
 * The port has never asked for one.
 *
 * The vendor tree asks per frame, in the descriptor: AX_TXD_SPE_RPT, bit 10
 * of txdesc.h's dword9, tagged with AX_TXD_SW_DEFINE, the low four bits of
 * dword10.  With a 24-byte WD BODY those two dwords are WD INFO dword 3 and
 * dword 4, which is exactly where trx_desc_8852b.c puts them -- info->spe_rpt
 * into wdi->dword3 and info->sw_define into wdi->dword4 -- and both are
 * dwords this port has so far left at zero.
 *
 * The answer does not come back as another type-6 packet.  Both the vendor
 * tree and mainline leave the special-report path pointed at the firmware
 * processor rather than at the host, so the firmware is what reads the report
 * and it forwards it as a C2H: category MAC, class FWCMD_C2H_CL_MISC,
 * function FWCMD_C2H_FUNC_CCXRPT, whose content is the six words
 * FWCMD_C2H_CCXRPT_DWORD0..DWORD5 -- read at c2h->content + 0 and + 12 by
 * fwofld.c's get_ccxrpt_event(), at buf + 0 and + 12 by its
 * mac_ccxrpt_parsing(), and as rpt->w2 and rpt->w5 by mainline's
 * rtw89_mac_c2h_tx_rpt().  The same six words this port already decodes, so
 * only the delivery has to be recognised.
 *
 * The tag is what makes a report attributable.  Zero is what an untagged
 * frame carries, so the protected data frame carries a non-zero one and the
 * report that comes back with it is the report about that frame; a report
 * whose tag is zero belongs to something else.  The two Discovers of a window
 * carry two different tags, because they carry two different header-with-LLC
 * lengths and a report has to say which of the two it is about.
 */

#define K1_RTL8852BS_TXD_SPE_RPT                (1u << 10)
#define K1_RTL8852BS_TXD_SW_DEFINE_MASK         0xfu
#define K1_RTL8852BS_TXRPT_TAG_NONE             0xffu
#define K1_RTL8852BS_TXRPT_TAG_DATA             0x1u
#define K1_RTL8852BS_TXRPT_TAG_DATA_MAINLINE    0x2u
#define K1_RTL8852BS_TXRPT_TAG_ARP              0x3u
#define K1_RTL8852BS_TXRPT_TAG_ARP_BROADCAST    0x4u
#define K1_RTL8852BS_TXRPT_TAG_LOOPBACK         0x5u
#define K1_RTL8852BS_TXRPT_TAG_DHCP_REQUEST     0x6u
#define K1_RTL8852BS_TXRPT_TAG_ARP_CLAIM        0x7u
#define K1_RTL8852BS_TXRPT_TAG_ARP_SERVE        0x8u
#define K1_RTL8852BS_TXRPT_TAG_ICMP_ECHO        0x9u
#define K1_RTL8852BS_TXRPT_TAG_ICMP_SERVE       0xau
#define K1_RTL8852BS_RXDESC_PACKET_TYPE_C2H     10u
#define K1_RTL8852BS_CCXRPT_C2H_CATEGORY        1u
#define K1_RTL8852BS_CCXRPT_C2H_CLASS           0x9u
